const localeOptions: ReadonlyArray<{ value: Locale; labelKey: TranslationKey }> = [
  { value: "system", labelKey: "language.system" },
  { value: "en", labelKey: "language.en" },
  { value: "zh-CN", labelKey: "language.zh-CN" },
  { value: "zh-TW", labelKey: "language.zh-TW" },
  { value: "ja", labelKey: "language.ja" },
  { value: "ko", labelKey: "language.ko" },
];

export { localeOptions };

function getSystemLanguages(): readonly string[] {
  if (typeof navigator === "undefined") return [];
  if (navigator.languages?.length) return navigator.languages;
  return navigator.language ? [navigator.language] : [];
}

export function resolveSystemLocale(languages: readonly string[] = getSystemLanguages()): ResolvedLocale {
  for (const candidate of languages) {
    const language = candidate.trim().replace(/_/g, "-").toLowerCase();
    if (!language) continue;
    if (language === "zh" || language === "zh-cn" || language === "zh-sg" || language.startsWith("zh-hans")) return "zh-CN";
    if (language === "zh-tw" || language === "zh-hk" || language === "zh-mo" || language.startsWith("zh-hant")) return "zh-TW";
    if (language === "ja" || language.startsWith("ja-")) return "ja";
    if (language === "ko" || language.startsWith("ko-")) return "ko";
    if (language === "en" || language.startsWith("en-")) return "en";
  }
  return "en";
}

export function normalizeLocale(value: string | null | undefined): Locale {
  return value === "en" || value === "zh-CN" || value === "zh-TW" || value === "ja" || value === "ko" || value === "system"
    ? value
    : "system";
}

function readStoredLocale(): Locale {
  try {
    return normalizeLocale(window.localStorage.getItem(LOCALE_STORAGE_KEY));
  } catch {
    return "system";
  }
}

function persistLocale(locale: Locale) {
  try {
    window.localStorage.setItem(LOCALE_STORAGE_KEY, locale);
  } catch {
    // Language preference is optional when local storage is unavailable.
  }
}

function interpolate(template: string, values?: TranslationValues): string {
  if (!values) return template;
  return template.replace(/\{([^}]+)\}/g, (placeholder, key) => String(values[key] ?? placeholder));
}

interface I18nContextValue {
  locale: Locale;
  resolvedLocale: ResolvedLocale;
  setLocale: (locale: Locale) => void;
  t: Translate;
}

const I18nContext = createContext<I18nContextValue | null>(null);

const fallbackI18nValue: I18nContextValue = {
  locale: "en",
  resolvedLocale: "en",
  setLocale: () => {},
  t: (key, values) => {
    const supplementalTemplate = supplementalCopy.en[key as SupplementalTranslationKey];
    const communityTemplate = communityCopy.en[key as CommunityTranslationKey];
    const template = supplementalTemplate ?? communityTemplate ?? english[key as keyof typeof english];
    return interpolate(template, values);
  },
};

export function I18nProvider({ children }: { children: ReactNode }) {
  const [locale, setLocalePreference] = useState<Locale>(readStoredLocale);
  const [systemLanguageVersion, setSystemLanguageVersion] = useState(0);
  const resolvedLocale = useMemo(
    () => (locale === "system" ? resolveSystemLocale() : locale),
    [locale, systemLanguageVersion],
  );

  useEffect(() => {
    document.documentElement.lang = resolvedLocale;
  }, [resolvedLocale]);

  useEffect(() => {
    if (locale !== "system") return;
    const refreshSystemLanguage = () => setSystemLanguageVersion((version) => version + 1);
    window.addEventListener("languagechange", refreshSystemLanguage);
    return () => window.removeEventListener("languagechange", refreshSystemLanguage);
  }, [locale]);

  const setLocale = useCallback((nextLocale: Locale) => {
    const normalizedLocale = normalizeLocale(nextLocale);
    setLocalePreference(normalizedLocale);
    persistLocale(normalizedLocale);
  }, []);

  const t = useCallback<Translate>((key, values) => {
    const supplementalTemplate = supplementalCopy[resolvedLocale][key as SupplementalTranslationKey]
      ?? supplementalCopy.en[key as SupplementalTranslationKey];
    const communityTemplate = communityCopy[resolvedLocale][key as CommunityTranslationKey];
    const template = supplementalTemplate ?? communityTemplate ?? translations[resolvedLocale][key as keyof typeof english];
    return interpolate(template, values);
  }, [resolvedLocale]);

  const value = useMemo<I18nContextValue>(() => ({ locale, resolvedLocale, setLocale, t }), [locale, resolvedLocale, setLocale, t]);

  return <I18nContext.Provider value={value}>{children}</I18nContext.Provider>;
}

export function useI18n(): I18nContextValue {
  const context = useContext(I18nContext);
  return context ?? fallbackI18nValue;
}
